<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<mappingRoot xmlns="http://www.ibm.com/2008/ccl/Mapping" xmlns:map="default" domainID="com.ibm.msl.mapping.xml" domainIDExtension="mb" mainMap="true" targetNamespace="default" version="8.0.5.0">
    <inlinedXMLSchema>
        <![CDATA[<?xml version="1.0" encoding="UTF-8" standalone="no"?> 
<xsd:schema xmlns:xsd="http://www.w3.org/2001/XMLSchema"> 
    
        
   
  <xsd:element name="message" nillable="true"> 
      
     
    <xsd:complexType> 
        
       
      <xsd:sequence> 
          
         
        <xsd:element name="Status" nillable="true" type="xsd:string"/> 
          
       
      </xsd:sequence> 
        
     
    </xsd:complexType> 
      
   
  </xsd:element> 
    
        
   
  <xsd:element name="otp" nillable="true" type="xsd:string"/> 
    
        
   
  <xsd:element name="id" nillable="true" type="xsd:string"/> 
    
    
 
</xsd:schema> 
]]>
    </inlinedXMLSchema>
    <input path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/JsonDomainMsg.xsd" var="var"/>
    <input inlinedXMLSchema="true" path="../schema_0.xsd" var="var2"/>
    <output path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/JsonDomainMsg.xsd" var="var1"/>
    <output path="jar:file://!com/ibm/msl/mapping/cache/xsds/cache.xsd" var="var3"/>
    <imports>
        <import kind="java" location="otp.optMapping" namespace="xalan://otp.optMapping"/>
    </imports>
    <namespaces>
        <namespace kind="supplement" prefix="io" uri="http://www.ibm.com/iib/msl/json"/>
        <namespace kind="supplement" prefix="out" uri="http://www.ibm.com/msl/cache/1.0"/>
        <namespace kind="extension" prefix="optMapping" uri="xalan://otp.optMapping"/>
    </namespaces>
    <generation engine="xquery"/>
    <mappingDeclaration name="OtpGen_Mapping">
        <input namespace="http://www.ibm.com/iib/msl/json" path="$var/mb:msg(JSON,assembly,JSON,Properties)" var="MessageAssembly">
            <cast castType="userDefined" path="$MessageAssembly/JSON/Data/type('anyType')" qualifier="{http://www.ibm.com/iib/msl/json}JSONObject" ref="var"/>
            <cast castType="userDefined" path="$MessageAssembly/JSON/spath('Data',2)/any" qualifier="id" ref="var2"/>
            <cast castType="userDefined" path="$MessageAssembly/JSON/spath('Data',2)/any" qualifier="otp" ref="var2"/>
        </input>
        <output namespace="http://www.ibm.com/iib/msl/json" path="$var1/mb:msg(JSON,assembly,JSON,Properties)" var="MessageAssembly1">
            <cast castType="userDefined" path="$MessageAssembly1/JSON/Data/type('anyType')" qualifier="{http://www.ibm.com/iib/msl/json}JSONObject" ref="var1"/>
            <cast castType="userDefined" path="$MessageAssembly1/JSON/spath('Data',2)/any" qualifier="id" ref="var2"/>
            <cast castType="userDefined" path="$MessageAssembly1/JSON/spath('Data',2)/any" qualifier="otp" ref="var2"/>
            <cast castType="userDefined" path="$MessageAssembly1/JSON/spath('Data',2)/any" qualifier="message" ref="var2"/>
        </output>
        <move>
            <input path="$MessageAssembly/Properties"/>
            <output path="$MessageAssembly1/Properties"/>
        </move>
        <move>
            <input path="$MessageAssembly/JSON/spath('Data',2)/id"/>
            <output path="$MessageAssembly1/JSON/spath('Data',2)/id"/>
        </move>
        <cachePut mode="upsert">
            <input path="$MessageAssembly/JSON/spath('Data',2)/otp" var="otp"/>
            <input path="$MessageAssembly/JSON/spath('Data',2)/id" var="id"/>
            <output path="$var3/CachePut"/>
            <assign value="OtpService">
                <output path="MapName"/>
            </assign>
            <assign value="60">
                <output path="TimeToLive"/>
            </assign>
            <move>
                <input path="$otp/."/>
                <output path="Value"/>
            </move>
            <move>
                <input path="$id/."/>
                <output path="Key"/>
            </move>
        </cachePut>
        <assign value="Success">
            <output path="$MessageAssembly1/JSON/spath('Data',2)/message/Status"/>
        </assign>
        <move>
            <input path="$MessageAssembly/JSON/spath('Data',2)/otp"/>
            <output path="$MessageAssembly1/JSON/spath('Data',2)/otp"/>
        </move>
    </mappingDeclaration>
</mappingRoot>
